'use strict';
let workbookHeaderContext=null;
function closeWorkbookContext(focus=false){document.getElementById('workbook-context-menu')?.remove();workbookHeaderContext=null;if(focus&&workbookDocument())restoreWorkbookFocus();}
function validWorkbookContext(c,editing=false){return c&&activeWorkbook===c.state&&c.index===activeWorkbook.sheetIndex&&c.key===activeWorkbook.key&&c.version===activeWorkbook.recordVersion&&Boolean(workbookDocument(editing));}
function contextAddress(c){if(c.axis==='cell')return c.address;const sheet=c.state.book.sheets[c.index];return c.axis==='column'?XlsxPackage.address(c.start,1)+':'+XlsxPackage.address(c.end,sheet.rows):XlsxPackage.address(1,c.start)+':'+XlsxPackage.address(sheet.columns,c.end);}
function selectHeaderContext(c){c.state.range=contextAddress(c);const area=WorkbookFormat.range(c.state.book.sheets[c.index],c.state.range);c.state.anchor=XlsxPackage.address(area.first.column,area.first.row);c.state.selected=c.state.anchor;c.state.editingCell=null;c.state.selectedPicture=null;selectWorkbookCell(c.state.selected);paintWorkbookPictureSelection();}
function mutateWorkbookContext(c,action){
  if(!validWorkbookContext(c,true)||c.state.saving)throw new Error('Dokumen tidak dapat diubah.');
  const state=c.state,backup=WorkbookFormat.snapshot(state.book,c.index),redo=[...(state.redo||[])],undo=[...(state.undo||[])];state.historyGroup=null;if(!workbookCheckpoint())return;
  try{action();state.historyGroup=null;workbookChanged();}catch(error){WorkbookFormat.restore(state.book,backup);state.undo=undo;state.redo=redo;state.historyGroup=null;renderWorkbookSheet();throw error;}
}
function contextStyle(c){const sheet=c.state.book.sheets[c.index],point=XlsxPackage.position(c.state.selected),cell=sheet.cells.get(c.state.selected);return c.state.book.styles[Number(cell?.getAttribute('s')??WorkbookStructure.defaultStyle(sheet,point.row,point.column))]||{};}
function formatHeaderContext(c,properties){mutateWorkbookContext(c,()=>{if(c.axis==='cell')for(const [property,value] of Object.entries(properties))WorkbookFormat.format(c.state.book,c.index,c.address,property,value);else WorkbookStructure.formatAxis(c.state.book,c.index,c.axis,c.start,c.end,properties);});}
function showContextCellFormat(c){
  if(!validWorkbookContext(c,true))return;const style=contextStyle(c),initial={fontName:style.fontName||'Arial',fontSize:Math.round((style.fontSize||11)*2)/2,bold:Boolean(style.bold),italic:Boolean(style.italic),underline:Boolean(style.underline),color:style.color||'#152c49',background:style.background||'#ffffff',horizontal:style.horizontal||'left',vertical:style.vertical||'top',wrap:Boolean(style.wrap),numFmt:[0,1,2,9,10,14,49].includes(style.numFmt)?style.numFmt:0};
  const fonts=[...new Set([...WorkbookFormat.fonts,...c.state.book.styles.map(style=>style.fontName).filter(Boolean)])];
  const choices=(name,label,values)=>`<div class="field"><label for="context-${name}">${label}</label><select data-native-select id="context-${name}" name="${name}">${values.map(([value,label])=>`<option value="${esc(value)}" ${String(initial[name])===String(value)?'selected':''}>${esc(label)}</option>`).join('')}</select></div>`;
  showModal(`${modalHeading('Format Cells')}<form id="context-cell-format"><div class="form-grid">${choices('fontName','Font sel',fonts.map(font=>[font,font]))}<div class="field"><label for="context-font-size">Ukuran font</label><input id="context-font-size" name="fontSize" type="number" min="1" max="409" step="0.5" value="${initial.fontSize}" required></div><div class="field"><label for="context-color">Warna teks</label><input id="context-color" name="color" type="color" value="${initial.color}"></div><div class="field"><label for="context-background">Warna sel</label><input id="context-background" name="background" type="color" value="${initial.background}"></div>${choices('horizontal','Perataan horizontal',[['left','Kiri'],['center','Tengah'],['right','Kanan']])}${choices('vertical','Perataan vertikal',[['top','Atas'],['center','Tengah'],['bottom','Bawah']])}${choices('numFmt','Format angka',[[0,'General'],[1,'Integer'],[2,'Decimal'],[9,'Percent'],[10,'Percent (2 decimals)'],[14,'Date'],[49,'Text']])}${choices('borders','Garis sel',[['keep','Pertahankan'],['all','Semua garis'],['none','Tanpa garis']])}<div class="context-format-checks field full">${[['bold','Bold'],['italic','Italic'],['underline','Underline'],['wrap','Wrap Text']].map(([name,label])=>`<label><input name="${name}" type="checkbox" ${initial[name]?'checked':''}>${label}</label>`).join('')}</div></div><div id="context-format-error" class="form-error" role="alert"></div><div class="form-actions"><button type="button" class="btn btn-secondary" data-action="close-modal">Batal</button><button type="submit" class="btn btn-primary">Terapkan Format</button></div></form>`);
  document.getElementById('context-cell-format').onsubmit=event=>{event.preventDefault();try{const data=new FormData(event.target),properties={};for(const name of Object.keys(initial)){const value=typeof initial[name]==='boolean'?data.has(name):typeof initial[name]==='number'?Number(data.get(name)):String(data.get(name));if(value!==initial[name])properties[name]=value;}if(data.get('borders')!=='keep')properties.borders=String(data.get('borders'));if(Object.keys(properties).length)formatHeaderContext(c,properties);modal.close();restoreWorkbookFocus();}catch(error){document.getElementById('context-format-error').textContent=error.message;}};
}
function clipboardHeaderContext(c,cut){
  if(!validWorkbookContext(c,cut))return;const state=c.state,sheet=state.book.sheets[c.index],original=state.range;let last=1;
  for(const [ref,cell] of sheet.cells){const p=WorkbookReference.parse(ref);if(p[c.axis]>=c.start&&p[c.axis]<=c.end&&(WorkbookEngine.child(cell,'v')||WorkbookEngine.child(cell,'is')||WorkbookEngine.child(cell,'f')))last=Math.max(last,p[c.axis==='column'?'row':'column']);}
  state.range=c.axis==='column'?XlsxPackage.address(c.start,1)+':'+XlsxPackage.address(c.end,last):XlsxPackage.address(1,c.start)+':'+XlsxPackage.address(last,c.end);
  try{copyWorkbookSelection(cut);}finally{state.range=original;highlightWorkbookRange();}
  state.copyArea={sheetIndex:c.index,area:WorkbookFormat.range(sheet,original)};paintWorkbookSelection();
}
async function changeWorkbookAxis(c,mode){
  if(!validWorkbookContext(c,true)||c.state.saving)return;
  const state=c.state,snapshot=db,actor=currentUser.id,edits=state.edits;state.saving=true;document.getElementById('workbook-save-status').textContent='Mengubah struktur worksheet...';
  try{
    const plan=await WorkbookStructure.plan(state.book,c.index,c.axis,c.start,c.end-c.start+1,mode);
    if(!validWorkbookContext(c,true)||db!==snapshot||currentUser.id!==actor||state.edits!==edits)throw new Error('Data berubah. Buka kembali permintaan.');
    state.saving=false;state.historyGroup=null;if(!workbookCheckpoint('structure',true))return;
    WorkbookStructure.commit(state.book,plan);state.historyGroup=null;state.copyArea=null;state.selectedPicture=null;const sheet=state.book.sheets[c.index],number=Math.min(c.start,c.axis==='row'?sheet.rows:sheet.columns);state.range=state.selected=XlsxPackage.address(c.axis==='column'?number:1,c.axis==='row'?number:1);state.anchor=state.selected;workbookChanged();restoreWorkbookFocus();
  }catch(error){toast(error.message,true);}finally{state.saving=false;if(activeWorkbook===state&&workbookDocument()){renderWorkbookSheet();restoreWorkbookFocus();}}
}
function unhideContext(c){
  const sheet=c.state.book.sheets[c.index],sizes=c.state.gridLayout[c.axis==='column'?'x':'y'];let start=c.start,end=c.end;
  if(start===end){while(start>1&&sizes[start-1]===sizes[start-2])start--;const max=c.axis==='column'?sheet.columns:sheet.rows;while(end<max&&sizes[end+1]===sizes[end])end++;}
  mutateWorkbookContext(c,()=>WorkbookStructure.visibility(c.state.book,c.index,c.axis,start,end,false));
}
async function runWorkbookContext(c,action){
  closeWorkbookContext();if(!validWorkbookContext(c,action!=='copy'))return;
  try{
    if(action==='copy'||action==='cut'){if(c.axis==='cell'){selectHeaderContext(c);copyWorkbookSelection(action==='cut');}else clipboardHeaderContext(c,action==='cut');}
    else if(action==='paste'||action==='paste-special'){selectHeaderContext(c);await showWorkbookPaste(action==='paste-special');}
    else if(action==='insert'||action==='delete'){if(c.axis==='cell')showCellStructureChoice(c,action);else await changeWorkbookAxis(c,action);}
    else if(action==='clear'){if(c.axis==='cell')clearWorkbookCellContext(c);else mutateWorkbookContext(c,()=>WorkbookStructure.clear(c.state.book,c.index,c.axis,c.start,c.end));}
    else if(action==='format')showContextCellFormat(c);
    else if(action==='link')showWorkbookCellLink(c);
    else if(action==='size')showWorkbookDimension(c.axis);
    else if(action==='hide'){mutateWorkbookContext(c,()=>WorkbookStructure.visibility(c.state.book,c.index,c.axis,c.start,c.end,true));const edges=c.state.gridLayout[c.axis==='row'?'y':'x'];let n=c.end+1;while(n<edges.length&&edges[n]===edges[n-1])n++;if(n>=edges.length){n=c.start-1;while(n>0&&edges[n]===edges[n-1])n--;}if(n>0){c.state.range=c.state.anchor=c.state.selected=XlsxPackage.address(c.axis==='column'?n:1,c.axis==='row'?n:1);selectWorkbookCell(c.state.selected);restoreWorkbookFocus();}}
    else if(action==='unhide')unhideContext(c);
    else if(action==='unhide-rows'||action==='unhide-columns'){const axis=action==='unhide-rows'?'row':'column';mutateWorkbookContext(c,()=>WorkbookStructure.visibility(c.state.book,c.index,axis,1,c.state.book.sheets[c.index][axis==='row'?'rows':'columns'],false));}
  }catch(error){toast(error.message,true);}
}
function openWorkbookContext(header,x,y){
  if(!workbookDocument())return;closeWorkbookContext();const state=activeWorkbook,sheet=state.book.sheets[state.sheetIndex],corner=header.hasAttribute('data-workbook-corner'),axis=header.dataset.row?'row':'column',number=Number(header.dataset.row||header.dataset.column||1),area=workbookSelectionArea(),same=axis==='column'?area.first.row===1&&area.last.row===sheet.rows&&number>=area.first.column&&number<=area.last.column:area.first.column===1&&area.last.column===sheet.columns&&number>=area.first.row&&number<=area.last.row;
  const cell=header.matches('.workbook-cell'),point=cell?XlsxPackage.position(header.dataset.cell):null,inside=point&&point.row>=area.first.row&&point.row<=area.last.row&&point.column>=area.first.column&&point.column<=area.last.column;
  const merge=cell?sheet.merges.find(m=>m.start===header.dataset.cell):null;
  const c={state,index:state.sheetIndex,key:state.key,version:state.recordVersion,axis:cell?'cell':axis,start:same?area.first[axis]:number,end:same?area.last[axis]:number,address:cell?(inside?workbookRange():merge?merge.start+':'+XlsxPackage.address(merge.last.column,merge.last.row):header.dataset.cell):null};workbookHeaderContext=c;selectHeaderContext(c);
  const writable=Boolean(workbookDocument(true))&&!state.saving,menu=document.createElement('div');menu.id='workbook-context-menu';menu.className='workbook-context-menu';menu.setAttribute('role','dialog');menu.setAttribute('aria-label',axis==='column'?'Menu kolom':'Menu baris');
  const actions=corner?[['unhide-rows','Unhide All Rows'],['unhide-columns','Unhide All Columns']]:[['cut','Cut'],['copy','Copy'],['paste','Paste'],['paste-special','Paste Special...'],['insert','Insert'],['delete','Delete'],['clear','Clear Contents'],['format','Format Cells...'],...(cell?[['link','Hyperlink...']]:[['size',axis==='column'?'Column Width...':'Row Height...'],['hide','Hide'],['unhide','Unhide']])];
  const style=contextStyle(c);menu.innerHTML=`${corner?'':`<div class="context-mini-toolbar" aria-label="Format cepat"><button type="button" data-ctx-format="bold" aria-label="Bold" aria-pressed="${Boolean(style.bold)}" ${writable?'':'disabled'}><b>B</b></button><button type="button" data-ctx-format="italic" aria-label="Italic" aria-pressed="${Boolean(style.italic)}" ${writable?'':'disabled'}><i>I</i></button><button type="button" data-ctx-format="underline" aria-label="Underline" aria-pressed="${Boolean(style.underline)}" ${writable?'':'disabled'}><u>U</u></button><label title="Warna teks">A<input type="color" data-ctx-color="color" aria-label="Warna teks cepat" value="${style.color||'#152c49'}" ${writable?'':'disabled'}></label><label title="Warna sel">&#9632;<input type="color" data-ctx-color="background" aria-label="Warna sel cepat" value="${style.background||'#ffffff'}" ${writable?'':'disabled'}></label></div>`}<label class="visually-hidden" for="context-menu-search">Search the menus</label><input id="context-menu-search" type="search" placeholder="Search the menus" autocomplete="off"><div role="menu">${actions.map(([action,label])=>`<button type="button" role="menuitem" tabindex="-1" data-ctx-action="${action}" ${writable||action==='copy'?'':'disabled'}>${label}</button>`).join('')}</div><p class="small muted context-no-results" hidden>Menu tidak ditemukan.</p>`;
  document.body.appendChild(menu);const scale=workbookPointerScale(document.querySelector('.workbook-workspace'));menu.style.maxHeight=(innerHeight-16)/scale.y+'px';menu.style.maxWidth=(innerWidth-16)/scale.x+'px';const rect=menu.getBoundingClientRect();menu.style.left=Math.max(8,Math.min(x,innerWidth-rect.width-8))/scale.x+'px';menu.style.top=Math.max(8,Math.min(y,innerHeight-rect.height-8))/scale.y+'px';
  const search=menu.querySelector('#context-menu-search');search.oninput=()=>{let shown=0;menu.querySelectorAll('[data-ctx-action]').forEach(button=>{button.hidden=!button.textContent.toLowerCase().includes(search.value.toLowerCase().trim());if(!button.hidden)shown++;});menu.querySelector('.context-no-results').hidden=Boolean(shown);};
  menu.onclick=event=>{const button=event.target.closest('[data-ctx-action]');if(button&&!button.disabled)runWorkbookContext(c,button.dataset.ctxAction);const format=event.target.closest('[data-ctx-format]');if(format&&!format.disabled){try{const property=format.dataset.ctxFormat;formatHeaderContext(c,{[property]:!contextStyle(c)[property]});format.setAttribute('aria-pressed',String(Boolean(contextStyle(c)[property])));}catch(error){toast(error.message,true);}}};
  menu.onchange=event=>{if(event.target.matches('[data-ctx-color]'))try{formatHeaderContext(c,{[event.target.dataset.ctxColor]:event.target.value});}catch(error){toast(error.message,true);}};
  menu.onkeydown=event=>{const buttons=[...menu.querySelectorAll('[data-ctx-action]')].filter(b=>!b.hidden&&!b.disabled),at=buttons.indexOf(document.activeElement);if(event.key==='Escape'){event.preventDefault();closeWorkbookContext(true);}else if(['ArrowDown','ArrowUp','Home','End'].includes(event.key)){event.preventDefault();const next=event.key==='Home'?0:event.key==='End'?buttons.length-1:(at+(event.key==='ArrowDown'?1:-1)+buttons.length)%buttons.length;buttons[next]?.focus();}else if(event.key==='Enter'&&event.target===search){event.preventDefault();buttons[0]?.click();}};
  search.focus({preventScroll:true});
}
document.addEventListener('pointerdown',event=>{if(event.button===2&&event.target.closest('#workbook-grid .workbook-cell')&&workbookDocument())event.preventDefault();},true);
document.addEventListener('contextmenu',event=>{const header=event.target.closest('#workbook-grid th[data-row],#workbook-grid th[data-column],#workbook-grid th[data-workbook-corner],#workbook-grid .workbook-cell');if(header&&workbookDocument()){event.preventDefault();openWorkbookContext(header,event.clientX,event.clientY);if(header.matches('.workbook-cell'))document.getElementById('workbook-context-menu').setAttribute('aria-label','Menu sel');}});
document.addEventListener('keydown',event=>{if(!workbookDocument()||!(event.key==='ContextMenu'||event.key==='F10'&&event.shiftKey))return;const point=XlsxPackage.position(activeWorkbook.selected),sheet=activeWorkbook.book.sheets[activeWorkbook.sheetIndex],area=workbookSelectionArea(),row=area.first.column===1&&area.last.column===sheet.columns,column=area.first.row===1&&area.last.row===sheet.rows;const header=document.querySelector(row?'th[data-row="'+point.row+'"]':column?'th[data-column="'+point.column+'"]':'.workbook-cell[data-cell="'+activeWorkbook.selected+'"]');if(header){event.preventDefault();const r=header.getBoundingClientRect();openWorkbookContext(header,r.left+8,r.bottom);}});
document.addEventListener('pointerdown',event=>{const menu=document.getElementById('workbook-context-menu');if(menu&&!menu.contains(event.target))closeWorkbookContext();},true);
// At zoom the workspace may auto-scroll after a context click. The fixed popup
// stays usable; user wheel/scrollbar gestures and worksheet scrolling dismiss it.
document.addEventListener('scroll',event=>{const menu=document.getElementById('workbook-context-menu');if(menu&&!menu.contains(event.target)&&event.target!==document.getElementById('main-content'))closeWorkbookContext();},true);
document.addEventListener('wheel',event=>{const menu=document.getElementById('workbook-context-menu');if(menu&&!menu.contains(event.target))closeWorkbookContext();},{capture:true,passive:true});
window.addEventListener('resize',()=>closeWorkbookContext());window.addEventListener('hashchange',()=>closeWorkbookContext());window.addEventListener('storage',()=>closeWorkbookContext());
